-- Seed: price snapshots collected locally via CDP (PET→SP, LATAM cash + Smiles miles+cash).
-- Idempotent: replaces any prior rows with source=local-cdp-sweep, then inserts the
-- deduped set (fixed collected_at). Source artifacts: scripts/collect/out/*/snapshots.jsonl

DELETE FROM public.price_snapshots
WHERE source = 'local-cdp-sweep';

ON CONFLICT DO NOTHING;

